    {'padas': ['tāḍito yamadūtena tadbhojī tatra tiṣṭhati |', 'tatastrijanmani bhavetkṛṣṇavarṇaḥ paśuḥ sati'], 'num': '|| 105 ||', 'gloss': ''},
