    {'padas': ['dhānyādisasyaṃ tāmbūlaṃ yo haretsuraviprayoḥ |', 'āsanaṃ ca tathā talpaṃ cūrṇakuṇḍe prayāti saḥ'], 'num': '|| 107 ||', 'gloss': ''},
