    {'padas': ['karoti cakraṃ viprāṇāṃ hṛtvā dravyaṃ ca yo janaḥ |', 'sa vaseccakrakuṇḍe ca śatābdaṃ daṇḍatāḍitaḥ'], 'num': '|| 110 ||', 'gloss': ''},
